const PROJECT_RISK_TABLE_FIELD = "custom_project_risks";

let cachedRiskLevels = null;
let cachedRiskLevelsPromise = null;

function set_project_risk_queries(frm) {
    frm.set_query("owner_person", PROJECT_RISK_TABLE_FIELD, (doc, cdt, cdn) => {
        const row = locals[cdt][cdn];
        const link_doctype = row?.owner_link_doctype;
        if (link_doctype === "User") {
            return { filters: { enabled: 1 } };
        }
        return {};
    });

    frm.set_query("responsible_person", PROJECT_RISK_TABLE_FIELD, (doc, cdt, cdn) => {
        const row = locals[cdt][cdn];
        const link_doctype = row?.responsible_link_doctype;
        if (link_doctype === "User") {
            return { filters: { enabled: 1 } };
        }
        return {};
    });
}

async function get_link_value(doctype, name) {
    if (!name) {
        return null;
    }
    const response = await frappe.db.get_value(doctype, name, "value");
    return response?.message?.value ?? null;
}

async function get_active_risk_levels() {
    if (cachedRiskLevels) {
        return cachedRiskLevels;
    }
    if (cachedRiskLevelsPromise) {
        return cachedRiskLevelsPromise;
    }

    cachedRiskLevelsPromise = frappe.db
        .get_list("Risk Level", {
            fields: ["name", "value"],
            filters: { enabled: 1 },
            order_by: "value desc",
            limit: 1000
        })
        .then((levels) => {
            cachedRiskLevels = (levels || []).map((level) => ({
                name: level.name,
                value: Number(level.value)
            }));
            cachedRiskLevelsPromise = null;
            return cachedRiskLevels;
        })
        .catch((error) => {
            cachedRiskLevelsPromise = null;
            throw error;
        });

    return cachedRiskLevelsPromise;
}

async function update_risk_level(cdt, cdn) {
    const row = locals[cdt][cdn];
    if (!row || !row.impact || !row.probability) {
        frappe.model.set_value(cdt, cdn, "level", "");
        return;
    }

    const [impact_value, probability_value] = await Promise.all([
        get_link_value("Risk Impact", row.impact),
        get_link_value("Risk Probability", row.probability)
    ]);

    if (impact_value === null || probability_value === null) {
        frappe.model.set_value(cdt, cdn, "level", "");
        return;
    }

    const score = Number(impact_value) * Number(probability_value);
    const levels = await get_active_risk_levels();
    const matched_level = (levels || []).find(
        (level) => Number.isFinite(level.value) && score >= level.value
    );
    const level_name = matched_level ? matched_level.name : "";

    frappe.model.set_value(cdt, cdn, "level", level_name || "");
}

frappe.ui.form.on("Project", {
    setup: function(frm) {
        set_project_risk_queries(frm);
    }
});

frappe.ui.form.on("Project Risk", {
    impact: function(frm, cdt, cdn) {
        update_risk_level(cdt, cdn);
    },
    probability: function(frm, cdt, cdn) {
        update_risk_level(cdt, cdn);
    },
    owner_link_doctype: function(frm, cdt, cdn) {
        frappe.model.set_value(cdt, cdn, "owner_person", "");
    },
    responsible_link_doctype: function(frm, cdt, cdn) {
        frappe.model.set_value(cdt, cdn, "responsible_person", "");
    }
});
